-- Market history is generated by the optional data updater; WoW makes no HTTP calls.
local core=MarketeerForeverCore
local function money(c)
  c=math.floor(c+.5);local g=math.floor(c/10000);local s=math.floor(c%10000/100);local n=c%100
  if g>0 then return g..'g '..s..'s '..n..'c' end
  if s>0 then return s..'s '..n..'c' end
  return n..'c'
end
local function label(parent,font,x,y,width)
  local t=parent:CreateFontString(nil,'OVERLAY',font);t:SetPoint('TOPLEFT',parent,'TOPLEFT',x,y);if width then t:SetWidth(width);t:SetJustifyH('LEFT') end;return t
end
local function button(parent,caption,x,y,w,action)
  local b=CreateFrame('Button',nil,parent,'BackdropTemplate');b:SetSize(w,23);b:SetPoint('TOPLEFT',parent,'TOPLEFT',x,y)
  b:SetBackdrop({bgFile='Interface\\Buttons\\WHITE8X8',edgeFile='Interface\\Buttons\\WHITE8X8',edgeSize=1});b:SetBackdropColor(.07,.09,.08,1);b:SetBackdropBorderColor(.20,.38,.28,1)
  local t=b:CreateFontString(nil,'OVERLAY','GameFontHighlightSmall');t:SetPoint('CENTER');t:SetText(caption);b.caption=t
  b:SetScript('OnEnter',function(self)self:SetBackdropBorderColor(.30,.78,.48,1)end);b:SetScript('OnLeave',function(self)self:SetBackdropBorderColor(.20,.38,.28,1)end);b:SetScript('OnClick',action);return b
end
local function dataFor(id)
  local d=_G.MarketeerForeverHistory;local market=core.Market()
  if type(d)~='table' or (d.schemaVersion~=1 and d.schemaVersion~=2) or d.market~=market or type(d.generatedAt)~='number' or type(d.items)~='table' then return nil,nil end
  local encoded=d.items[id];if type(encoded)~='string' then return {},d end
  local points={};local base=math.floor(d.generatedAt/3600)*3600
  for age,price in encoded:gmatch('([%da-z]+),([%da-z]+)') do
    age,price=tonumber(age,d.schemaVersion==2 and 36 or 10),tonumber(price,d.schemaVersion==2 and 36 or 10)
    if age and age<=336 and price and price>0 then points[#points+1]={time=base-age*3600,price=price/2,age=age} end
  end
  table.sort(points,function(a,b)return a.time<b.time end);return points,d
end
local function itemNameFor(id)
  local lookup=GetItemInfo or (C_Item and C_Item.GetItemInfo)
  if lookup then local ok,n=pcall(lookup,id);if ok and not (issecretvalue and issecretvalue(n)) and type(n)=='string' and n~='' then return n end end
  local catalog=_G.MarketeerForeverItemNames
  local n=type(catalog)=='table' and catalog.schemaVersion==1 and type(catalog.items)=='table' and catalog.items[id]
  if type(n)=='string' and n~='' then return n end
end
