  xleft:ClearAllPoints();xleft:SetPoint('TOPLEFT',chart,'BOTTOMLEFT',0,-6)
  xright:ClearAllPoints();xright:SetPoint('TOPRIGHT',chart,'BOTTOMRIGHT',0,-6)
  note:ClearAllPoints();note:SetPoint('BOTTOMLEFT',p,'BOTTOMLEFT',22,20)
